// One-shot (re-runnable) corpus-v2 admission pipeline:
//   drafts dir (5 files, byte-identical to the preserved 2026-08-27
//   originals or regenerated by build-draft.py) ->
//   admitted fragments (docs/evals/analysis/corpus-c2/*.json + MANIFEST) ->
//   composed v2 datasets (docs/evals/analysis/{map,digest,validation}-v2.json)
//
// Deterministic: same inputs, byte-identical outputs (fixed createdAt, no
// clock, no RNG). Usage:
//   npx tsx scripts/evals/corpus-v2/run-admit.ts --drafts <dir> [--check]
// --check verifies the committed outputs byte-match instead of writing.

import { createHash } from "node:crypto";
import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
import { join } from "node:path";
import { admitCorpusC2, type DraftFiles } from "../../../src/lib/evals/corpus-v2-admit";
import { composeV2Dataset, serializeDataset } from "../../../src/lib/evals/corpus-v2-compose";
import { validateAnalysisEvalDataset, type AnalysisEvalDataset } from "../../../src/lib/evals/contracts";

const ROOT = join(__dirname, "..", "..", "..");
const EVALS_DIR = join(ROOT, "docs", "evals", "analysis");
const FRAGMENTS_DIR = join(EVALS_DIR, "corpus-c2");

/** the admitted corpus's authorship instant (fixed — never the clock) */
const CREATED_AT = "2026-09-03T00:00:00Z";

const DRAFT_FILE_NAMES = {
  mapCapacity: "map-capacity-c2-draft.json",
  mapAdversarial: "map-adversarial-c2-draft.json",
  reduceCapacity: "reduce-capacity-c2-draft.json",
  digestLate: "digest-late-c2-draft.json",
  validation: "validation-c2-draft.json",
} as const;

function sha256(text: string | Buffer): string {
  return createHash("sha256").update(text).digest("hex");
}

function arg(name: string): string | null {
  const i = process.argv.indexOf(name);
  return i >= 0 ? process.argv[i + 1] ?? null : null;
}

const draftsDir = arg("--drafts");
const checkOnly = process.argv.includes("--check");
if (!draftsDir) {
  console.error("usage: run-admit.ts --drafts <dir-with-the-5-draft-files> [--check]");
  process.exit(2);
}

const draftBytes: Record<string, string> = {};
const drafts = Object.fromEntries(
  Object.entries(DRAFT_FILE_NAMES).map(([key, file]) => {
    const bytes = readFileSync(join(draftsDir, file), "utf8");
    draftBytes[file] = bytes;
    return [key, JSON.parse(bytes) as Record<string, unknown>];
  }),
) as unknown as DraftFiles;

const fragments = admitCorpusC2(drafts);

const outputs: Array<{ path: string; bytes: string }> = [];
const fragmentHashes: Record<string, string> = {};
for (const [name, cases] of [
  ["map-c2-cases.json", fragments.map],
  ["digest-c2-cases.json", fragments.digest],
  ["validation-c2-cases.json", fragments.validation],
] as const) {
  const bytes = JSON.stringify(cases, null, 2) + "\n";
  fragmentHashes[name] = sha256(bytes);
  outputs.push({ path: join(FRAGMENTS_DIR, name), bytes });
}
outputs.push({
  path: join(FRAGMENTS_DIR, "MANIFEST.json"),
  bytes:
    JSON.stringify(
      {
        generator: "scripts/evals/corpus-v2/build-draft.py (byte-identical to the preserved 2026-08-27 tools/build.py) -> src/lib/evals/corpus-v2-admit.ts",
        admittedAt: CREATED_AT,
        draftSha256: Object.fromEntries(
          Object.values(DRAFT_FILE_NAMES).map((f) => [f, sha256(draftBytes[f])]),
        ),
        fragmentSha256: fragmentHashes,
      },
      null,
      2,
    ) + "\n",
});

const V2 = [
  { v1File: "map-v1.json", v2File: "map-v2.json", datasetVersion: "map-v2", cases: fragments.map },
  { v1File: "digest-v1.json", v2File: "digest-v2.json", datasetVersion: "digest-v2", cases: fragments.digest },
  { v1File: "validation-v1.json", v2File: "validation-v2.json", datasetVersion: "validation-v2", cases: fragments.validation },
] as const;

for (const { v1File, v2File, datasetVersion, cases } of V2) {
  const v1 = JSON.parse(readFileSync(join(EVALS_DIR, v1File), "utf8")) as AnalysisEvalDataset;
  const v2 = composeV2Dataset(v1, cases, { datasetVersion, createdAt: CREATED_AT });
  const errs = validateAnalysisEvalDataset(v2, v2.workload);
  if (errs.length > 0) {
    console.error(`${v2File}: ${errs.length} validation error(s):`);
    for (const e of errs) console.error(`  - ${e}`);
    process.exit(1);
  }
  outputs.push({ path: join(EVALS_DIR, v2File), bytes: serializeDataset(v2) });
}

let drift = 0;
for (const { path, bytes } of outputs) {
  if (checkOnly) {
    const existing = existsSync(path) ? readFileSync(path, "utf8") : null;
    if (existing !== bytes) {
      drift++;
      console.error(`DRIFT: ${path} ${existing === null ? "missing" : "differs from deterministic regeneration"}`);
    } else {
      console.log(`ok: ${path}`);
    }
  } else {
    mkdirSync(join(path, ".."), { recursive: true });
    writeFileSync(path, bytes);
    console.log(`wrote: ${path} (${bytes.length} bytes, sha256 ${sha256(bytes).slice(0, 12)})`);
  }
}
if (checkOnly && drift > 0) process.exit(1);
console.log(checkOnly ? "byte-identical regeneration verified." : "admission outputs written.");
